        if ($servicioCertimail) {
            $this->addUsingAlias(ServicioCertimailPeer::SERVICIOCERTIMAIL_ID, $servicioCertimail->getServiciocertimailId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

